import java.util.*;
public class ContainsDuplicate {public static boolean containsDuplicate(int[]a){Set<Integer>s=new HashSet<>();for(int v:a)if(!s.add(v))return true;return false;}public static void main(String[]args){Scanner sc=new Scanner(System.in);System.out.print("Array size: ");int n=sc.nextInt();if(n<0){System.out.println("Invalid size");sc.close();return;}int[]a=new int[n];System.out.println("Enter values:");for(int i=0;i<n;i++)a[i]=sc.nextInt();System.out.println("Contains duplicate: "+containsDuplicate(a));sc.close();}}